(6216855, 916801, 59796, '<td valign="top">My pick for blue in this challenge. Very nice concept and execution - very realistic if you leave out the evenly distributed stars :)</td>', 'My pick for blue in this challenge. Very nice concept and execution - very realistic if you leave out the evenly distributed stars :)', '2010-11-08 17:28:33.000000', NULL, 1),
(6216859, 917885, 59796, '<td valign="top">But for the rough edge of the moon, it''s way too realistic - fantastic execution and fabulous lighting. Hope this ribbons.</td>', 'But for the rough edge of the moon, it''s way too realistic - fantastic execution and fabulous lighting. Hope this ribbons.', '2010-11-08 17:29:46.000000', NULL, 1),
(6216862, 917068, 59796, '<td valign="top">Inviting for a nice and pleasant hike on a cloudy day :) Nicely done! The folds in the fabric sky are the only nit I can pick after staring for a long time. Hope this ribbons.</td>', 'Inviting for a nice and pleasant hike on a cloudy day :) Nicely done! The folds in the fabric sky are the only nit I can pick after staring for a long time. Hope this ribbons.', '2010-11-08 17:31:58.000000', NULL, 1),
(6216867, 917596, 59796, '<td valign="top">Neat concept. The colors are fabulous and are appropriate for an early morning scene. The light on the lighthouse is a little too harsh for early morning though :) My top 5 for this challenge.</td>', 'Neat concept. The colors are fabulous and are appropriate for an early morning scene. The light on the lighthouse is a little too harsh for early morning though :) My top 5 for this challenge.', '2010-11-08 17:38:04.000000', NULL, 1),
(6216868, 917599, 59796, '<td valign="top">Very cool skyline - surreal atmosphere. My top 5 for this challenge.</td>', 'Very cool skyline - surreal atmosphere. My top 5 for this challenge.', '2010-11-08 17:38:56.000000', NULL, 1),
(6216869, 917592, 59796, '<td valign="top">I hope people know Ayers Rock from before. Love the idea - a little more space around the rock would''ve probably emphasized more how lonely it is in the landscape. Well done.</td>', 'I hope people know Ayers Rock from before. Love the idea - a little more space around the rock would''ve probably emphasized more how lonely it is in the landscape. Well done.', '2010-11-08 17:40:06.000000', NULL, 1),
(6216872, 917268, 59796, '<td valign="top">Great concept! Love the powdered mountains and the star reflections. The island reflection is kind of jarring though - it doesn''t look like water waves like the star reflections do. Maybe black plexi instead of a mirror would''ve given better reflection there. But a fantastic landscape - and nicely lighted like it is indeed night. My top 5.</td>', 'Great concept! Love the powdered mountains and the star reflections. The island reflection is kind of jarring though - it doesn''t look like water waves like the star reflections do. Maybe black plexi instead of a mirror would''ve given better reflection there. But a fantastic landscape - and nicely lighted like it is indeed night. My top 5.', '2010-11-08 17:43:03.000000', NULL, 1),
(6217001, 917800, 108069, '<td valign="top">Clever idea. Well done... BUT next time make the drops drop. As circles it''s just not the same. No penalty, just saying for next time. I like it.</td>', 'Clever idea. Well done... BUT next time make the drops drop. As circles it''s just not the same. No penalty, just saying for next time. I like it.', '2010-11-08 19:13:07.000000', NULL, 1),
